import { ASK_TEMPLATES, type MapAtom, type Part, parse } from './reference-ask';

/**
 * The fake agent's grammar, generated by code from the approved map and the section 5 table (docs/estate.md, "The
 * ask templates"), never from what the generator says about itself: for each atom that declares an act
 * (`fields.ask`, a verbatim span of the estate with its provenance), every ask a row of the table writes for it,
 * with its context as the situation when the atom declares one; for a fixed act the table ties to a tool, every ask
 * a row writes with it, for each guard whose matcher lists the tool. The fake sets an atom off only when an ask
 * equals one of its texts byte for byte (dispatch.mjs). Nothing reads a word of an ask.
 */
export type AskGrammar = { asks: Record<string, string[]> };

type Fill = { act?: string; situation?: string; span?: string };

/** The text of a template with its slots filled; the optional group written when `withGroup`; undefined if a slot is empty. */
function render(parts: readonly Part[], fill: Fill, withGroup: boolean): string | undefined {
  let out = '';
  for (const part of parts) {
    if ('lit' in part) out += part.lit;
    else if ('opt' in part) {
      if (!withGroup) continue;
      const inner = render(part.opt, fill, true);
      if (inner === undefined) return undefined;
      out += inner;
    } else {
      const value = fill[part.slot as keyof Fill];
      if (value === undefined) return undefined;
      out += value;
    }
  }
  return out;
}

const hasGroup = (parts: readonly Part[]): boolean => parts.some((part) => 'opt' in part);

/** The declared act of an atom: its text and its context, when the map gives them. */
function declared(atom: MapAtom): { text: string; context?: string } | undefined {
  const ask = (atom.fields as { ask?: unknown } | undefined)?.ask;
  if (typeof ask === 'string') return ask.trim() === '' ? undefined : { text: ask };
  if (ask === null || typeof ask !== 'object') return undefined;
  const { text, context } = ask as { text?: unknown; context?: unknown };
  if (typeof text !== 'string' || text.trim() === '') return undefined;
  return typeof context === 'string' && context.trim() !== '' ? { text, context } : { text };
}

export function askGrammar(atoms: readonly MapAtom[]): AskGrammar {
  const asks = ASK_TEMPLATES.filter((entry) => entry.kind === 'ask').map((entry) => parse(entry.template));
  const out = new Map<string, Set<string>>();
  const add = (text: string | undefined, id: string) => {
    if (text === undefined) return;
    out.set(text, (out.get(text) ?? new Set()).add(id));
  };
  // Every ask of every row for one act, with and without the situation the act declares.
  const write = (act: string, id: string, context?: string) => {
    for (const parts of asks) {
      add(render(parts, { act, span: act }, false), id);
      if (context === undefined || !hasGroup(parts)) continue;
      add(render(parts, { act, span: act, situation: context }, true), id);
    }
  };
  for (const atom of atoms) {
    const act = declared(atom);
    if (act) write(act.text, atom.id, act.context);
  }
  for (const row of ASK_TEMPLATES) {
    const slotted = parse(row.template).some((part) => 'slot' in part);
    if (row.kind !== 'act' || row.tools === undefined || slotted) continue;
    for (const atom of atoms) {
      const matcher = (atom.fields as { matcher?: unknown } | undefined)?.matcher;
      if (atom.kind !== 'guard' || typeof matcher !== 'string') continue;
      if (matcher.split('|').some((tool) => row.tools?.includes(tool))) write(row.template, atom.id);
    }
  }
  const texts = [...out.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return { asks: Object.fromEntries(texts.map((text) => [text, [...(out.get(text) ?? [])].sort()])) };
}
